import{_ as t,l as o,o as a,c as l,v as e,p as s,x as n,d as M,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"MiniCPM / MiniCPM-V","description":"","frontmatter":{"title":"MiniCPM / MiniCPM-V","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/minicpm.md","filePath":"llm/minicpm.md","lastUpdated":1789023840000}'),P={name:"llm/minicpm.md"};function c(B,i,h,C,d,E){const r=o("Mermaid");return a(),l("div",null,[i[1]||(i[1]=e('<h1 id="minicpm-minicpm-v" tabindex="-1">MiniCPM / MiniCPM-V <a class="header-anchor" href="#minicpm-minicpm-v" aria-label="Permalink to &quot;MiniCPM / MiniCPM-V&quot;">​</a></h1><div class="epigraph"><p>MiniCPM 要证明：在 1B–2B 非嵌入参数上，用可扩展的训练策略也能打到 7B–13B 的实用能力；MiniCPM-V 再把这一档容量接到手机能跑的多模态上。</p><footer>—— Hu 等，MiniCPM，2024；Yao 等，MiniCPM-V，2024</footer></div><p>面壁智能（ModelBest）与清华大学等合作的 MiniCPM，把「小模型」当成一等实验对象，而不是大模型压缩后的边角料。2024 年 4 月的技术报告给出 <strong>1.2B 与 2.4B 非嵌入参数</strong> 的稠密语言模型，配套风洞式超参搜索和 Warmup-Stable-Decay（WSD）学习率；随后 MiniCPM-V 把 SigLIP 与 perceiver 接到同一条端侧叙事上，2.5 档换用 Llama-3-8B 指令模型，宣称在 OpenCompass 上超过当时对照的 GPT-4V-1106。本篇把文本小模型与视觉系列写成一条产品线：先解决「小参数如何把数据吃完」，再解决「高分辨率如何压进手机内存」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Chinchilla 式算力最优把数据量钉在参数的约 20 倍；若小模型按这个比例早停，知识与指令都不够用。反过来，用余弦学习率把终点写死，想多训一截就要从头再来。MiniCPM 要问的是：在 <strong>不预先规定总 token 数</strong> 的前提下，能否让小模型持续吃数据，并在任意稳定阶段做一次衰减，得到不差于余弦终点的损失。这直接决定端侧模型能不能靠「同一检查点退火」做领域适应，而不是为每个垂直再训一个 7B。</p><p>多模态侧的约束更硬。云端 MLLM 用几百到上千视觉 token 换 OCR；手机既放不下 7B×长视觉前缀，也耗不起对应的 decode 带宽。MiniCPM-V 的问题因此是：在保留任意长宽比与约 180 万像素感知的同时，把视觉序列压到端侧可接受的长度。</p><h3 id="小模型的第三轴是可连续训练" tabindex="-1">小模型的第三轴是可连续训练 <a class="header-anchor" href="#小模型的第三轴是可连续训练" aria-label="Permalink to &quot;小模型的第三轴是可连续训练&quot;">​</a></h3><p>报告用大量小规模风洞实验选宽深比与学习率，再把同一套超参往 1B/2B 上搬。WSD 把训练分成预热、<strong>高学习率平台</strong>、衰减三段：平台期可以无限续训，衰减期损失会陡降，逼近「若用余弦、终点恰好在此刻」的包络。于是数据轴上的标度律可以用线性成本测量——对同一稳定检查点做不同长度的衰减，而不必为每个 \\(D\\) 重训。报告由此主张：相对 Hoffmann 等人的 Chinchilla 比，可达到的最优数据/参数比可以高得多。这是训练策略主张，不是说 2.4B 已经推翻 Kaplan 曲线。</p><p><span class="marginnote">「1.2B / 2.4B」计的是非嵌入参数。大词表时嵌入占比不低，对端侧显存仍要按全模型算。不要把非嵌入参数理解成磁盘上的检查点更小一号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>文本系列是解码器 Transformer，公开家族还包括 MiniCPM-DPO、MiniCPM-MoE、MiniCPM-128K。核心可复述的方法学是 WSD，而不是新的注意力核。记预热终点为 \\(W\\)、平台终点为 \\(T\\)、峰值学习率 \\(\\eta\\)，则</p> \\[\\mathrm{WSD}(s)=\\begin{cases} (s/W)\\,\\eta, &amp; s\\lt W,\\\\ \\eta, &amp; W\\le s\\le T,\\\\ f(s-T)\\,\\eta, &amp; s\\gt T, \\end{cases} \\]<p>\\(f\\) 为递减到 0 附近的衰减。衰减前的检查点可以继续用 \\(\\eta\\) 往前走，再另开一次衰减，对应「先通用预训练、再领域退火」而不丢平台期学到的统计。</p><h3 id="minicpm-v-自适应切块加-perceiver" tabindex="-1">MiniCPM-V：自适应切块加 perceiver <a class="header-anchor" href="#minicpm-v-自适应切块加-perceiver" aria-label="Permalink to &quot;MiniCPM-V：自适应切块加 perceiver&quot;">​</a></h3><p>视觉报告以 MiniCPM-Llama3-V 2.5 为旗舰叙述。结构三件套：SigLIP SoViT-400M/14 编码器、一层交叉注意力的 perceiver resampler、语言模型。高分辨率走 LLaVA-UHD 式<strong>自适应视觉编码</strong>：按原图与 ViT 预训练边长估计应切几片，每片更接近 SigLIP 见过的分辨率与长宽比，再编码、压缩、拼接。2.0 与 2.5 支持约 <strong>1.8M 像素</strong>（例如 1344×1344）与任意长宽比；1.0 仍是约 0.2M 像素的固定 448×448。perceiver 把每片（及全局）压成短前缀，使端侧内存不随像素线性爆炸——这与 InternVL2「每格 256 token」的账单策略不同，见 <a href="/llm/vision-token-compression">视觉 token 压缩</a>。</p><p>版本不要混：V 1.0 / 2.0 接 MiniCPM-2B；2.5 接 Llama-3-Instruct 8B，对齐侧用 RLAIF-V；2.0 用过 RLHF-V。多语依赖「多语 LLM + 相对少的多语图文」，报告写 30+ 语言。手机部署叙事包含量化、编译与 NPU，以当时开源 APK / 推理栈为准，本文不编帧率。</p>',16)),(a(),s(m,null,{default:n(()=>[p(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%BD%91%E9%A1%B5%E4%B8%8E%E6%8C%87%E4%BB%A4%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20WSD%5B%22WSD%EF%BC%9A%E9%A2%84%E7%83%AD%20%2F%20%E5%B9%B3%E5%8F%B0%20%2F%20%E8%A1%B0%E5%87%8F%22%5D%0A%20%20WSD%20--%3E%20TXT%5B%22MiniCPM%201.2B%20%2F%202.4B%22%5D%0A%20%20IMG%5B%22%E9%AB%98%E5%88%86%E8%BE%A8%E7%8E%87%E5%9B%BE%22%5D%20--%3E%20SLICE%5B%22LLaVA-UHD%20%E5%BC%8F%E5%88%87%E5%9D%97%22%5D%0A%20%20SLICE%20--%3E%20SIG%5B%22SigLIP-400M%22%5D%0A%20%20SIG%20--%3E%20PER%5B%22Perceiver%20%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20TXT%20--%3E%20V1%5B%22MiniCPM-V%202.0%20%E7%AB%AF%E4%BE%A7%22%5D%0A%20%20PER%20--%3E%20V1%0A%20%20PER%20--%3E%20V25%5B%22Llama3-V%202.5%22%5D%0A%20%20L3%5B%22Llama-3-8B%20Instruct%22%5D%20--%3E%20V25%0A"})]),fallback:n(()=>[...i[0]||(i[0]=[M(" Loading... ",-1)])]),_:1})),i[2]||(i[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>WSD 的机制是把「学表示」和「把权重收进低损失盆地」分开。高学习率平台保持可塑，损失不一定最低；一衰减，优化器才把已经形成的方向收紧。因此衰减曲线上的陡降不是数据突然变好，而是学习率日程的相位变化。连续训练时，小模型可以在远超 Chinchilla 的 token 上仍有增益，代价是重复数据与过拟合风险——报告用小模型包络说明「还能降」，没有声称 2.4B 应训到无限。</p><p>视觉侧，切块负责细节，perceiver 负责账单。LLM 只看见压缩后的查询，细字若在 resampler 里被平均掉，OCR 仍会失败；所以 1.8M 像素是<strong>编码器输入</strong>的覆盖，不等于 LLM 看到了 1.8M 个像素级 token。2.5 换 8B 语言骨干，世界知识与多语跟上，端侧代价从「2B 可进手机」变成「8B 需更强 NPU 或量化」。OpenCompass 超过某次 GPT-4V 快照，是综合榜设定下的结果，不是逐项文档理解支配所有闭源系统。</p><p><span class="marginnote">「GPT-4V 级别」是 MiniCPM-V 论文标题里的产品句。引用时应写明对照的是 GPT-4V-1106 与当时 OpenCompass 11 项，而不是未注明版本的 GPT-4o。端侧能跑取决于量化与运行时，不是 8B 权重的字面含义。</span></p><h3 id="和-phi、internvl2-的分工" tabindex="-1">和 Phi、InternVL2 的分工 <a class="header-anchor" href="#和-phi、internvl2-的分工" aria-label="Permalink to &quot;和 Phi、InternVL2 的分工&quot;">​</a></h3><p><a href="/llm/phi">Phi</a> 用教材式合成数据拧样本效率；MiniCPM 文本线更强调 <strong>WSD 与风洞超参</strong>，让小模型把更多真实 token 训完。两者都可以「小打大」，机制不同。InternVL2 用大视觉塔加大 LLM 追云端多模态；MiniCPM-V 把压缩放在 perceiver，优先延迟与内存。选端侧 OCR 助手看 MiniCPM-V 2.0/2.5；选 70B 级图文推理看 InternVL2 大档。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>WSD 的衰减长度与 \\(f\\) 的形状是超参，报告用小模型说明现象，2.4B 生产配方的精确步数以开源训练脚本为准，不要把附录里的 0.036B 曲线当成 2.4B 的日程。MiniCPM-MoE 与 128K 变体证明底座可扩展，但不自动继承 V 系列的切块代码。</p><p>许可与底座：2.5 受 Llama 3 社区许可约束；2.0 随 MiniCPM 自身条款。不要把 Apache 与 Llama 条款混写。后续 MiniCPM-V 2.6 等换 Qwen2、加视频，以当时仓库说明为准，不属于 2408.01800 正文的主体。幻觉方面，RLAIF-V 降的是对象幻觉基准上的率，不是事实性保证。</p><p><span class="marginnote">真实编号：Hu 等 <em>MiniCPM: Unveiling the Potential of Small Language Models with Scalable Training Strategies</em>，arXiv:2404.06395；Yao 等 <em>MiniCPM-V: A GPT-4V Level MLLM on Your Phone</em>，arXiv:2408.01800。LLaVA-UHD 是自适应切块的引用对象，不要把 MiniCPM-V 写成自创了一种与 UHD 无关的新网格算法。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MiniCPM 是面壁的 1.2B/2.4B 级小语言模型，卖点是风洞超参与 WSD 连续训练，而不是新注意力。</li><li>WSD 把高学习率平台与衰减拆开，便于续训、领域退火，以及更便宜地测数据标度。</li><li>MiniCPM-V 用 SigLIP + perceiver + 自适应切块，在约 1.8M 像素上做端侧多模态；2.5 换 Llama-3 8B。</li><li>「小打大」成立的范围是报告里的对照与 OpenCompass 设定；手机可跑取决于量化栈。</li><li>出处：arXiv:2404.06395；arXiv:2408.01800；OpenBMB MiniCPM / MiniCPM-V 仓库与模型卡。</li></ul>',12))])}const A=t(P,[["render",c]]);export{L as __pageData,A as default};
